pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address baseTokenAddr,
        address nftAddr,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        // Admissible domain: a pool initialized with distinct base token and NFT addresses,
        // any valid reserves/fees. Keep the domain wide so the fuzzer can pick any pair.
        vm.assume(baseTokenAddr != address(0));
        vm.assume(nftAddr != address(0));
        vm.assume(baseTokenAddr != nftAddr);

        c.initialize(
            baseTokenAddr,
            nftAddr,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        // General rule: after initialize, the pool's base token is exactly the address
        // supplied as _baseToken (and hence distinct from the pool's nft when the inputs differ).
        assertTrue(c.baseToken() == baseTokenAddr);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(address nft, uint16 feeRate, uint128 vBase, uint128 vNft, uint56 changeFee) public {
        // Admissible domain: pool pays no royalties / no stolen-nft oracle checks, fee rate must be legal,
        // and the NFT address must be nonzero so it is distinguishable from the native base token.
        vm.assume(nft != address(0));
        feeRate = uint16(bound(feeRate, 0, 5_000));

        c.initialize(
            address(0), // base token is native ETH
            nft,
            vBase,
            vNft,
            changeFee,
            feeRate,
            bytes32(0),
            false,
            false
        );

        // General rule: with baseToken initialized to the native token, the flash-loan fee token
        // is always the native token (address 0). The mutant stores the NFT address in baseToken,
        // so flashFeeToken() returns the nonzero NFT address.
        assertTrue(c.flashFeeToken() == address(0));
    }
}

