// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        // The feeRate must be admissible; additionally require that the two deciding
        // values genuinely differ after truncation so the rule is decidable.
        vm.assume(_feeRate <= 5_000);
        vm.assume(uint56(_feeRate) != _changeFee);

        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            // General rule: after a successful initialize, changeFee always equals
            // the _changeFee argument supplied by the caller.
            assertTrue(c.changeFee() == _changeFee);
        } catch {
            // initialize must never revert for admissible inputs (feeRate <= 5000,
            // not yet initialized); reverting here also fails the invariant.
            assertTrue(false);
        }
    }
}
